When validating upstream status objects, explicitly verify that all expected validator keys are present and have the correct status rather than checking only the values of the present keys.

```javascript
  const expectedValidatorKeys = [
    'question_level_page_range_locator_validator_status',
    'page_screenshot_assets_validator_status',
  ];
  if (!isRecord(manifest.upstream_validator_status)) {
    pushError(errors, 'upstream_validator_status_missing', '/upstream_validator_status', 'upstream validator status is missing or malformed');
  } else {
    for (const key of expectedValidatorKeys) {
      if (!(key in manifest.upstream_validator_status)) {
        pushError(errors, 'upstream_validator_key_missing', `/upstream_validator_status/${key}`, `expected validator key "${key}" is missing`);
      } else if (manifest.upstream_validator_status[key] !== 'pass') {
        pushError(errors, 'upstream_validator_not_pass', `/upstream_validator_status/${key}`, `upstream validator "${key}" must pass`);
      }
    }
  }
