+  const paths = pathsFromOptions(opts);
+  const generatedAt = opts.generatedAt ?? GENERATED_AT;
+  const inputs = {
+    diagnostics: opts.diagnostics ?? [],
+    questionLevelLocator: opts.questionLevelLocator,
+    questionLevelLocatorValidator: opts.questionLevelLocatorValidator,
+    pageScreenshotAssets: opts.pageScreenshotAssets,
+    pageScreenshotAssetsValidator: opts.pageScreenshotAssetsValidator,
+    controlledPackageReceipt: opts.controlledPackageReceipt,
+  };
+  const manifest = buildManifest({
+    root,
+    paths,
+    generatedAt,
+    questionLevelLocator: inputs.questionLevelLocator,
+    questionLevelLocatorValidator: inputs.questionLevelLocatorValidator,
+    pageScreenshotAssets: inputs.pageScreenshotAssets,
+    pageScreenshotAssetsValidator: inputs.pageScreenshotAssetsValidator,
+    controlledPackageReceipt: inputs.controlledPackageReceipt,
+    gitTrackedBinaryPaths: opts.gitTrackedBinaryPaths,
